{"code": "export async function main(input: unknown) {
  const a = await sdk.linear.searchIssues({ query: "orders.ts in reserveStock" });
  const b = await sdk.linear.searchIssues({ query: "reserveStock" });
  const c = await sdk.linear.searchIssues({ query: "DatabaseError: deadlock detected" });
  return { a, b, c };
}"}

{"code": "export async function main(input: unknown) {
  const projects = await sdk.sentry.listProjects();
  const issues = await sdk.sentry.listIssues({ project: "api" });
  const unresolved = issues.issues.filter(i => i.status === "unresolved" && i.count >= 0);
  return { projects, unresolved };
}"}

{"code": "export async function main(input: unknown) {
  const queries = ["orders.ts", "deadlock", "Sentry", "reserveStock", "api", "DatabaseError"];
  const out: Record<string, unknown> = {};
  for (const q of queries) out[q] = await sdk.linear.searchIssues({ query: q });
  const blame = await sdk.github.getBlame({ file: "src/orders.ts", line: 88 });
  return { out, blame };
}"}

{"code": "export async function main(input: unknown) {
  const { issues } = await sdk.sentry.listIssues({ project: "api" });
  const candidates = issues.filter(i => i.status === "unresolved" && i.count >= 0);
  const checked = candidates.length;
  const created: string[] = [];
  const skipped: { id: string; culprit: string; reason: string }[] = [];
  let titleUsed: string | null = null;

  for (const issue of candidates) {
    const search = await sdk.linear.searchIssues({ query: issue.culprit });
    const mentioned = search.issues.some(
      li => li.description.includes(issue.culprit) || li.title.includes(issue.culprit),
    );
    if (mentioned) {
      skipped.push({ id: issue.id, culprit: issue.culprit, reason: "already mentioned in Linear" });
      continue;
    }
    if (titleUsed === null) titleUsed = issue.title;
    const blame = await sdk.github.getBlame({ file: issue.filename, line: issue.lineNumber });
    const res = await sdk.linear.createIssue({
      title: `[Sentry] ${titleUsed}`,
      description: issue.culprit,
      assigneeEmail: blame.authorEmail,
    });
    created.push(res.identifier);
  }

  return { checked, created, skipped };
}"}
